{"function":"() => {
const props=['outline-style','outline-width','outline-color','box-shadow','border-color','background-color'];
const out={};
for (const id of ['nome','cpf','servico','unidade','data-preferencial','descricao']) {
  const el=document.getElementById(id);
  const before=props.map(p=>getComputedStyle(el).getPropertyValue(p));
  el.focus();
  const after=props.map(p=>getComputedStyle(el).getPropertyValue(p));
  out[id]={before,after, active: document.activeElement===el, fv: el.matches(':focus-visible'), cls: el.className};
  el.blur();
}
return out;}"}

