function bg(el){ while(el){ const c=getComputedStyle(el).backgroundColor; if(c!=='rgba(0, 0, 0, 0)'&&c!=='transparent') return c; el=el.parentElement;} return 'rgb(255,255,255)'; }
const sels=['.trilha-servico a[href]:not(.br-button)','.trilha-servico [aria-current]','.retorno-campo','.mensagem-retorno .message-body','.mensagem-retorno .message-title','#cpf-apoio','.table-title','tbody td','thead th','.paginacao-anteriores a.page:not(.active)','.paginacao-anteriores a.active','.apoio-solicitacao','.upload-button span','.marca-govbr','.br-skiplink a','.mensagem-retorno .close .br-button','.mensagem-retorno .icon i'];
const out={};
for(const s of sels){ const e=document.querySelector(s); if(!e){out[s]=null;continue;} const cs=getComputedStyle(e); out[s]={color:cs.color, bg:bg(e), fs:cs.fontSize, fw:cs.fontWeight, fst:cs.fontStyle, ff:cs.fontFamily.slice(0,30)}; }
const ph=getComputedStyle(document.getElementById('cpf'),'::placeholder'); out.placeholder={color:ph.color};
return out; }"}

